from __future__ import annotations
import html,random,json,shutil
from pathlib import Path
from data import TEAMS,DRIVERS,CIRCUITS,PODIUMS,POINTS,ART
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'dist';SRC=ROOT/'public'
H=lambda x:html.escape(str(x),quote=True)
teamdict={x[0]:x for x in TEAMS}; driverdict={x[0]:x for x in DRIVERS}; circuitdict={x[0]:x for x in CIRCUITS}
results=[]
for n,podium in enumerate(PODIUMS):
 others=[d[0] for d in DRIVERS if d[0] not in podium];random.Random(1327+n).shuffle(others)
 results.append([*podium,*others])
pointmap={d[0]:sum(POINTS[order.index(d[0])] for order in results) for d in DRIVERS}
# Ensure season's narrative is coherent: home favourite wins, principal challenger second, tactician third.
assert sorted(pointmap,key=pointmap.get,reverse=True)[:3]==['yassine-el-mansouri','isla-bennett','haruka-sato'],sorted(pointmap.items(),key=lambda x:-x[1])[:5]
teampts={i:sum(pointmap[d[0]] for d in DRIVERS if d[5]==i) for i in range(8)}

def img(n,prefix='',attrs='',alt=None):return f'<img src="{prefix}assets/img/{n:02d}-{ART[n]}.webp" alt="{H(alt or ART[n].replace("-"," "))}" loading="lazy" decoding="async" {attrs}>'
def a(href,text,cls='',extra=''):return f'<a href="{href}" class="{cls}" {extra}>{text}</a>'
def glyph(n):return f'<span class="glyph" aria-hidden="true">{n}</span>'
def topnav(active,prefix):
 links=[('championship/','Championship'),('calendar/','Calendar'),('circuits/','Circuits'),('teams/','Teams'),('drivers/','Drivers'),('standings/','Standings'),('race-centre/','Race centre')]
 lis=''.join(a(prefix+u,t,'nav-link '+('active' if active==u.rstrip('/') else '')) for u,t in links)
 return f'''<div class="topline"><span>IONRUSH / MOROCCO 2032</span><span>AN ORIGINAL FICTIONAL CHAMPIONSHIP&nbsp;&nbsp; <span class="online-dot"></span> SEASON ARCHIVE</span></div><header class="header"><a class="brand" href="{prefix or './'}" aria-label="IONRUSH home">ION<span class="brand-slash">/</span>RUSH<span class="brand-mark">®</span></a><nav class="desktop-nav" aria-label="Primary navigation">{lis}</nav><a class="nav-action" href="{prefix}race-centre/">RACE CONTROL <span>↗</span></a><button class="menu-toggle" aria-controls="mobile-menu" aria-expanded="false" aria-label="Open navigation"><span></span><span></span></button></header><nav class="mobile-menu" id="mobile-menu" aria-label="Mobile navigation" hidden>{lis}{a(prefix+'technology/','Technology','nav-link')}{a(prefix+'stories/','Stories','nav-link')}</nav>'''
def footer(prefix):return f'''<footer class="footer"><div class="footer-main"><div><span class="eyebrow">THE GRID IS OUR WORLD</span><div class="footer-wordmark">ION<span>/</span>RUSH.</div><p>Eight cities. One electric racing championship.<br>Built in imagination. Driven across Morocco.</p></div><div class="footer-links"><div><small>THE CHAMPIONSHIP</small>{a(prefix+'championship/','The series')}{a(prefix+'calendar/','Race calendar')}{a(prefix+'standings/','Standings')}{a(prefix+'race-centre/','Race centre')}</div><div><small>EXPLORE</small>{a(prefix+'circuits/','Circuits')}{a(prefix+'teams/','Teams')}{a(prefix+'drivers/','Drivers')}{a(prefix+'technology/','Technology')}{a(prefix+'stories/','Stories')}</div></div></div><div class="footer-bottom"><span>© IONRUSH 2032 — A CONCEPTUAL MOTORSPORT WORLD</span><span>FICTIONAL SERIES · FICTIONAL DATA · NO LIVE EVENTS</span><a href="#top">BACK TO TOP ↑</a></div></footer>'''
def layout(title,description,content,route='index.html',active='',heroimg=1):
 depth=len(Path(route).parts)-1;prefix='../'*depth
 css=prefix+'assets/site.css';js=prefix+'assets/site.js'
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101216"><meta name="description" content="{H(description)}"><meta property="og:title" content="{H(title)} — IONRUSH"><meta property="og:description" content="{H(description)}"><meta property="og:type" content="website"><meta property="og:image" content="{prefix}assets/img/{heroimg:02d}-{ART[heroimg]}.webp"><title>{H(title)} — IONRUSH Morocco 2032</title><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="{css}"><script src="{js}" defer></script></head><body id="top">{topnav(active,prefix)}<main id="main">{content}</main>{footer(prefix)}</body></html>'''
def write(route,title,desc,content,active='',heroimg=1):
 p=OUT/route;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(layout(title,desc,content,route,active,heroimg),encoding='utf8')
def arrow():return '<span aria-hidden="true">↗</span>'
def section_heading(kicker,title,aside='',light=False):return f'<div class="section-heading"><div><span class="eyebrow">{kicker}</span><h2>{title}</h2></div><p>{aside}</p></div>'
def banner(title,desc,label,imgn,prefix='',modifier=''):
 return f'<section class="inner-hero {modifier}" style="--hero-img:url(\'{prefix}assets/img/{imgn:02d}-{ART[imgn]}.webp\')"><div class="inner-hero-overlay"></div><div class="inner-hero-content"><span class="eyebrow">{label}</span><h1>{title}</h1><p>{desc}</p></div></section>'
def num(n):return f'{n:02d}'
def race_card(c,idx,prefix=''):
 slug,city,cname,date,full,pn,typ,km,corners,path,desc=c
 winner=driverdict[results[idx][0]]
 return f'''<a class="circuit-card" href="{prefix}circuits/{slug}/"><img class="circuit-card-img" src="{prefix}assets/img/{pn:02d}-{ART[pn]}.webp" alt="{H(city)} — {H(cname)} racing circuit" loading="lazy" decoding="async"><div class="card-top"><span>R{num(idx+1)} / {date}</span><span>↗</span></div><div class="card-bottom"><span class="eyebrow">{typ.upper()}</span><h3 class="card-title-{'long' if len(city)>8 else ('short' if len(city)<7 else 'mid')}">{city}</h3><div class="card-under"><span>{cname}</span><span>{km:.2f} KM · {corners} TURNS</span></div></div></a>'''
def team_card(t,prefix=''):
 slug,short,full,country,color,photo,line,desc=t
 return f'<a class="team-card" href="{prefix}teams/{slug}/" style="--team-accent:{color}"><div class="team-card-top"><span>{country.upper()}</span><span>↗</span></div><div class="team-visual">{img(photo,prefix,alt=full+" electric racing car")}</div><div class="team-card-foot"><h3>{short}</h3><span class="team-accent-line"></span></div></a>'
def driver_card(d,prefix=''):
 slug,first,last,country,number,ti,photo,role,desc=d
 return f'<a class="driver-card" href="{prefix}drivers/{slug}/" style="--team-accent:{TEAMS[ti][4]}"><div class="driver-card-photo">{img(photo,prefix,alt=first+" "+last+" official driver portrait")}<span class="driver-number">{num(number)}</span></div><div class="driver-card-meta"><div><span class="eyebrow">{country.upper()} / {TEAMS[ti][1]}</span><h3>{first}<br><strong>{last.upper()}</strong></h3></div><span class="button-icon">↗</span></div></a>'
def standings_table(kind='driver',prefix='',limit=16):
 if kind=='driver':
  order=sorted(DRIVERS,key=lambda x:(-pointmap[x[0]],x[4]))[:limit]
  rows=''.join(f'<tr><td class="pos">{num(i)}</td><td><a class="rank-name" href="{prefix}drivers/{d[0]}/"><span class="rank-stripe" style="background:{TEAMS[d[5]][4]}"></span><span><b>{d[1]} {d[2]}</b><small>{TEAMS[d[5]][2]}</small></span></a></td><td class="mono">{num(d[4])}</td><td class="mono align-r"><b>{pointmap[d[0]]}</b></td></tr>' for i,d in enumerate(order,1))
  heads='<th>POS</th><th>DRIVER / TEAM</th><th>NO.</th><th class="align-r">PTS</th>'
 else:
  order=sorted(enumerate(TEAMS),key=lambda x:-teampts[x[0]])[:limit]
  rows=''.join(f'<tr><td class="pos">{num(i)}</td><td><a class="rank-name" href="{prefix}teams/{t[0]}/"><span class="rank-stripe" style="background:{t[4]}"></span><span><b>{t[2]}</b><small>{t[3]}</small></span></a></td><td class="mono">{len([d for d in DRIVERS if d[5]==ix])}</td><td class="mono align-r"><b>{teampts[ix]}</b></td></tr>' for i,(ix,t) in enumerate(order,1))
  heads='<th>POS</th><th>TEAM</th><th>DRIVERS</th><th class="align-r">PTS</th>'
 return f'<table class="ranking"><thead><tr>{heads}</tr></thead><tbody>{rows}</tbody></table>'
def round_chip(c,idx,prefix='',target='circuits'):
 slug,city,_,date,*_=c
 return f'<a class="round-chip" href="{prefix}{target}/{slug}/"><span class="mono">R{num(idx+1)}</span><strong>{city}</strong><small>{date}</small><span>↗</span></a>'
# site home
home=f'''
<section class="hero" style="--hero-img:url('assets/img/01-championship-hero.webp')"><div class="hero-overlay"></div><div class="hero-visual"><div class="hero-grid"></div></div><div class="hero-content"><div class="hero-top"><span class="eyebrow">THE ELECTRIC RACING CHAMPIONSHIP / 2032</span><span class="hero-status"><span class="online-dot"></span> EIGHT ROUNDS / MOROCCO</span></div><div class="hero-headline"><span>FULL</span><span class="text-lime">CHARGE.</span><span>NO LIMITS<span class="dot">.</span></span></div><div class="hero-lower"><p>Sixteen drivers. Eight teams.<br>One country built for speed.</p><a href="championship/" class="button button-lime">ENTER THE CHAMPIONSHIP {arrow()}</a></div></div><div class="hero-bottom-label"><span>01 / THE NEW ERA</span><span>SCROLL TO EXPLORE ↓</span></div></section>
<div class="ticker"><span class="ticker-tag">2032 SEASON</span><div class="ticker-items"><span>08 ROUNDS</span><i></i><span>08 TEAMS</span><i></i><span>16 DRIVERS</span><i></i><span>ALL-ELECTRIC</span><i></i><span>ONE CHAMPION</span></div><span class="ticker-right">MOROCCO ONLY ↗</span></div>
<section class="section intro-section"><div class="page-container"><div class="intro-grid"><div><span class="eyebrow">01 / THE SERIES</span><h2 class="massive-heading">THIS IS<br><span class="outline-text">NOT A</span><br>QUIET<br>SPORT.</h2></div><div class="intro-detail"><span class="vertical-mark">IR / 32</span><p>Across Morocco's coasts, mountains, cities and desert edge, the world's most ambitious electric racing grid goes all in.</p><p class="dim">A fully imagined championship. A world built with the precision of the real thing.</p><a href="championship/" class="text-link">DISCOVER THE SERIES ↗</a></div></div></div></section>
<section class="section section-cream"><div class="page-container">{section_heading('02 / THE CALENDAR','A COUNTRY.<br>EIGHT <em>CHALLENGES.</em>','Eight distinct circuits. Eight very different ways to win.')}<div class="circuit-scroll">{''.join(race_card(c,i) for i,c in enumerate(CIRCUITS))}</div><div class="section-footer-link"><span>ROUND 01 — ROUND 08</span>{a('calendar/','EXPLORE THE FULL CALENDAR ↗','text-link')}</div></div></section>
<section class="feature-race" style="--hero-img:url('assets/img/38-casablanca-night-duel.webp')"><div class="feature-race-shade"></div><div class="feature-race-content"><span class="eyebrow">03 / THE RIVALRY</span><h2>EVERY<br>SECOND<br><em>MATTERS.</em></h2><p>Revisit the decisive battles of the 2032 season with our fictional race replay experience.</p><a href="race-centre/" class="button button-lime">OPEN RACE CENTRE {arrow()}</a></div><div class="feature-race-counter"><strong>08</strong><span>RACE<br>ARCHIVES</span></div></section>
<section class="section teams-section"><div class="page-container">{section_heading('04 / THE PADDOCK','EIGHT TEAMS.<br>ONE TARGET.','Different philosophies. The same electric platform.')}<div class="home-teams">{''.join(team_card(x) for x in TEAMS[:4])}</div><div class="section-footer-link"><span>THE ENTIRE 2032 GRID</span>{a('teams/','MEET ALL TEAMS ↗','text-link')}</div></div></section>
<section class="section standings-section"><div class="page-container"><div class="standings-grid"><div><span class="eyebrow">05 / THE TITLE FIGHT</span><h2 class="massive-heading small">THE<br>POINTS<br>DON'T <span class="text-lime">LIE.</span></h2><p>Eight rounds. One final table. Every position counts.</p><a href="standings/" class="button button-outline">FULL STANDINGS ↗</a></div><div>{standings_table('driver',limit=5)}</div></div></div></section>
<section class="section section-cream home-tech"><div class="page-container"><div class="home-tech-layout"><div class="tech-copy"><span class="eyebrow">06 / THE MACHINE</span><h2>THE SCIENCE<br>OF <em>SPEED.</em></h2><p>A single chassis. Thousands of decisions. Explore the anatomy of the fictional IR-32 electric racing prototype.</p><a href="technology/" class="text-link">EXPLORE THE IR-32 ↗</a></div><div class="tech-photo">{img(40,attrs='alt="IR-32 electric prototype engineering cutaway"')}</div></div></div></section>
<section class="section stories-home"><div class="page-container">{section_heading('07 / FROM THE TRACK','BEYOND THE<br>CHEQUERED FLAG.','Three defining moments of the season.')}<div class="story-row"><a href="stories/#tangier" class="story-card">{img(37)}<span class="eyebrow">THE OPENING CHAPTER / TANGIER</span><h3>When the grid came alive <span>↗</span></h3></a><a href="stories/#casablanca" class="story-card">{img(38)}<span class="eyebrow">THE RIVALRY / CASABLANCA</span><h3>Side by side, under the lights <span>↗</span></h3></a><a href="stories/#marrakech" class="story-card">{img(39)}<span class="eyebrow">THE CROWN / MARRAKECH</span><h3>One final drive for history <span>↗</span></h3></a></div></div></section>
'''
write('index.html','The Electric Racing Championship','IONRUSH Morocco 2032. Eight original fictional circuits, eight teams and one electric racing title.',home)
