 guys=[d for d in DRIVERS if d[5]==ti]
 content=f'''<section class="team-detail-hero" style="--team-accent:{color}"><div class="page-container"><div class="team-dhead"><span class="eyebrow">TEAM {num(ti+1)} / THE 2032 GRID</span><span class="country-flag">{country.upper()}</span></div><h1>{short}<span>.</span></h1><p>{slogan}</p><div class="team-detail-img">{img(pn,'../../',alt=full+' IR-32 race car')}</div></div></section><section class="section section-cream"><div class="page-container"><div class="split-editorial"><div><span class="eyebrow">THE TEAM</span><h2 class="display-xl">ONE MACHINE.<br><em>A UNIQUE MINDSET.</em></h2></div><div><p class="lead">{desc}</p><p>Two drivers. One shared championship platform. A distinct approach to every race weekend.</p></div></div>{section_heading('THE LINE-UP','MEET THE<br>DRIVERS.')}<div class="driver-grid duo">{''.join(driver_card(d,'../../') for d in guys)}</div><div class="section-footer-link">{a('../../standings/','CHAMPIONSHIP STANDINGS ↗','text-link')}</div></div></section>'''
 write(f'teams/{slug}/index.html',full,f'Meet {full}, the {country} electric racing team of IONRUSH 2032.',content,'teams',pn)
